# Random Movie Clips - Pixel-matched GUI
$script:AppVersion = "1.1.0"
# Visual design uses the supplied reference image as the interface artwork.
# One random MP4 clip per movie; preserves source folders and creates <Movie Name>\backdrops
# Requires ffmpeg.exe and ffprobe.exe in PATH or beside this script.

Add-Type -AssemblyName System.Windows.Forms

# Keep the compiled EXE in the same DPI coordinate system as the .ps1 version.
# This must run before the first Form/control is created.
try {
    if ([Environment]::OSVersion.Version.Major -ge 6) {
        Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class ClipCreatorDpi {
    [DllImport("user32.dll")]
    public static extern bool SetProcessDPIAware();
}
"@ -ErrorAction SilentlyContinue
        [void][ClipCreatorDpi]::SetProcessDPIAware()
    }
} catch {
    # If DPI awareness is already established by the host, continue normally.
}

Add-Type -AssemblyName System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()

$script:CancelRequested = $false
$script:CreatedCount = 0
$script:StartTime = $null

function Find-Tool([string]$Name) {
    $local = Join-Path $PSScriptRoot "$Name.exe"
    if (Test-Path $local) { return $local }
    $cmd = Get-Command "$Name.exe" -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    return $null
}

function Add-Log([string]$Text, [System.Drawing.Color]$Color = [System.Drawing.Color]::Gainsboro) {
    $stamp = (Get-Date).ToString("HH:mm:ss")
    $txtLog.SelectionStart = $txtLog.TextLength
    $txtLog.SelectionLength = 0
    $txtLog.SelectionColor = $Color
    $txtLog.AppendText("[$stamp]  $Text" + [Environment]::NewLine)
    $txtLog.SelectionColor = $txtLog.ForeColor
    $txtLog.ScrollToCaret()
    [System.Windows.Forms.Application]::DoEvents()
}

# ----- Embedded reference artwork -----
$ImageBase64 = @"

"@
$bytes = [Convert]::FromBase64String($ImageBase64)
$stream = New-Object System.IO.MemoryStream(,$bytes)
$background = [System.Drawing.Image]::FromStream($stream)

# The reference artwork is 1536 x 1024. We use the exact same coordinate system.
$form = New-Object System.Windows.Forms.Form
$form.AutoScaleMode = [System.Windows.Forms.AutoScaleMode]::None
$form.Text = "Random Movie Clips"
$form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::None
$form.StartPosition = "CenterScreen"
$form.ClientSize = New-Object System.Drawing.Size(1536,1024)
$form.BackgroundImage = $background
$form.BackgroundImageLayout = [System.Windows.Forms.ImageLayout]::Stretch
$form.AutoScaleMode = [System.Windows.Forms.AutoScaleMode]::None
$form.Font = New-Object System.Drawing.Font("Segoe UI",10)
$form.KeyPreview = $true

# Scale down automatically if the working area is smaller than the artwork.
$wa = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
$scale = [Math]::Min($wa.Width / 1536.0, $wa.Height / 1024.0)
if ($scale -lt 1) {
    $form.ClientSize = New-Object System.Drawing.Size([int](1536*$scale), [int](1024*$scale))
    $form.BackgroundImageLayout = [System.Windows.Forms.ImageLayout]::Stretch
}

# Coordinate helper so controls follow the artwork if it is scaled.
function SX([int]$x) { return [int]($x * $form.ClientSize.Width / 1536.0) }
function SY([int]$y) { return [int]($y * $form.ClientSize.Height / 1024.0) }
function SW([int]$w) { return [int]($w * $form.ClientSize.Width / 1536.0) }
function SH([int]$h) { return [int]($h * $form.ClientSize.Height / 1024.0) }

# Transparent click target helper.
function New-Hotspot([int]$x,[int]$y,[int]$w,[int]$h) {
    $p = New-Object System.Windows.Forms.Panel
    $p.Location = New-Object System.Drawing.Point((SX $x),(SY $y))
    $p.Size = New-Object System.Drawing.Size((SW $w),(SH $h))
    $p.BackColor = [System.Drawing.Color]::Transparent
    $p.Cursor = [System.Windows.Forms.Cursors]::Hand
    $form.Controls.Add($p)
    return $p
}

