function New-OverlayLabel($x,$y,$w,$h,$text,$size=12,$bold=$false,$align="Left") {
    $l = New-Object System.Windows.Forms.Label
    $l.Location = New-Object System.Drawing.Point((SX $x),(SY $y))
    $l.Size = New-Object System.Drawing.Size((SW $w),(SH $h))
    $l.Text = $text
    $l.BackColor = [System.Drawing.Color]::FromArgb(239,246,252)
    $l.ForeColor = [System.Drawing.Color]::FromArgb(8,29,58)
    $style = if ($bold) {[System.Drawing.FontStyle]::Bold} else {[System.Drawing.FontStyle]::Regular}
    $l.Font = New-Object System.Drawing.Font("Segoe UI",[Math]::Max(6,($size-3.5)*$scale),$style)
    if ($align -eq "Center") { $l.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter }
    else { $l.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft }
    $form.Controls.Add($l)
    return $l
}

