# Visual pressed state for the four large bottom buttons.
# Since the buttons are part of the background artwork, a semi-transparent
# overlay gives them a clear "pushed in" appearance while held.
function Add-PressedEffect([System.Windows.Forms.Control]$control) {
    $control.Add_MouseDown({
        param($sender,$e)
        if ($e.Button -eq [System.Windows.Forms.MouseButtons]::Left) {
            $sender.BackColor = [System.Drawing.Color]::FromArgb(85,0,0,0)
            [System.Windows.Forms.Application]::DoEvents()
        }
    })
    $control.Add_MouseUp({
        param($sender,$e)
        $sender.BackColor = [System.Drawing.Color]::Transparent
        [System.Windows.Forms.Application]::DoEvents()
    })
    $control.Add_MouseLeave({
        param($sender,$e)
        $sender.BackColor = [System.Drawing.Color]::Transparent
    })
}

