using System;
using System.Runtime.InteropServices;

public static class NativeWindowMove
{
    [DllImport("user32.dll")]
    public static extern bool ReleaseCapture();

    [DllImport("user32.dll")]
    public static extern IntPtr SendMessage(
        IntPtr hWnd,
        int Msg,
        IntPtr wParam,
        IntPtr lParam
    );
}
"@
}

$drag.Add_MouseDown({
