    $about.Controls.Add($openaiLink)

    $poweredLabel = New-Object System.Windows.Forms.Label
    $poweredLabel.Text = "Video processing"
    $poweredLabel.Location = New-Object System.Drawing.Point(30,290)
    $poweredLabel.Size = New-Object System.Drawing.Size(210,28)
    $poweredLabel.Font = New-Object System.Drawing.Font("Segoe UI",10,[System.Drawing.FontStyle]::Bold)
    $poweredLabel.ForeColor = [System.Drawing.Color]::FromArgb(8,29,58)
    $about.Controls.Add($poweredLabel)

    $ffmpegLabel = New-Object System.Windows.Forms.Label
    $ffmpegLabel.Text = "FFmpeg"
    $ffmpegLabel.Location = New-Object System.Drawing.Point(245,290)
    $ffmpegLabel.Size = New-Object System.Drawing.Size(260,28)
    $ffmpegLabel.ForeColor = [System.Drawing.Color]::FromArgb(40,55,75)
    $about.Controls.Add($ffmpegLabel)

    $closeAbout = New-Object System.Windows.Forms.Button
    $closeAbout.Text = "OK"
    $closeAbout.Location = New-Object System.Drawing.Point(432,338)
    $closeAbout.Size = New-Object System.Drawing.Size(100,34)
    $closeAbout.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $closeAbout.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(190,200,210)
    $closeAbout.BackColor = [System.Drawing.Color]::White
    $closeAbout.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $about.AcceptButton = $closeAbout
    $about.Controls.Add($closeAbout)

    [void]$about.ShowDialog($form)
    $about.Dispose()
})

$hotClose.Add_Click({ $form.Close() })
$hotMin.Add_Click({ $form.WindowState = [System.Windows.Forms.FormWindowState]::Minimized })

$dlg = New-Object System.Windows.Forms.FolderBrowserDialog

$hotBrowseMovie.Add_Click({
    $dlg.Description = "Select your movies folder"
    if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        $txtMovie.Text = $dlg.SelectedPath
        if ([string]::IsNullOrWhiteSpace($txtOutput.Text)) {
            $txtOutput.Text = Join-Path $dlg.SelectedPath "Random Clips"
        }
    }
})

$hotBrowseOutput.Add_Click({
    $dlg.Description = "Select the output folder"
    if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        $txtOutput.Text = $dlg.SelectedPath
    }
})

$hotClear.Add_Click({ $txtLog.Clear() })

$hotOpen.Add_Click({
    if (Test-Path $txtOutput.Text) {
        Start-Process explorer.exe -ArgumentList "`"$($txtOutput.Text)`""
    } else {
        [System.Windows.Forms.MessageBox]::Show("The output folder does not exist yet.","Output Folder")
    }
})

$hotCheck.Add_Click({
    $ffmpeg = Find-Tool "ffmpeg"
    $ffprobe = Find-Tool "ffprobe"
    if ($ffmpeg -and $ffprobe) {
        [System.Windows.Forms.MessageBox]::Show("FFmpeg and FFprobe were found.`r`n`r`nFFmpeg:`r`n$ffmpeg`r`n`r`nFFprobe:`r`n$ffprobe","FFmpeg Check")
    } else {
        [System.Windows.Forms.MessageBox]::Show("FFmpeg and/or FFprobe could not be found.`r`n`r`nAdd them to PATH or place ffmpeg.exe and ffprobe.exe beside this script.","FFmpeg Check")
    }
})

$hotStop.Add_Click({
    $script:CancelRequested = $true
    Add-Log "Stop requested. Processing will stop after the current clip." ([System.Drawing.Color]::Orange)
})

$hotStart.Add_Click({
    $movieFolder = $txtMovie.Text.Trim()
    $outputFolder = $txtOutput.Text.Trim()
    $clipLength = [int]$numLength.Value
    $avoid = [int]$numAvoid.Value

    if (-not (Test-Path $movieFolder -PathType Container)) {
        [System.Windows.Forms.MessageBox]::Show("Please select a valid Movies Folder.","Movies Folder")
        return
    }
    if ([string]::IsNullOrWhiteSpace($outputFolder)) {
        [System.Windows.Forms.MessageBox]::Show("Please select an Output Folder.","Output Folder")
        return
    }

    $ffmpeg = Find-Tool "ffmpeg"
    $ffprobe = Find-Tool "ffprobe"
    if (-not $ffmpeg -or -not $ffprobe) {
        [System.Windows.Forms.MessageBox]::Show("FFmpeg or FFprobe was not found. Click Check FFmpeg for details.","FFmpeg Not Found")
        return
    }

    New-Item -ItemType Directory -Path $outputFolder -Force | Out-Null
    $exts = @(".mkv",".mp4",".avi",".mov",".m4v",".wmv",".mpg",".mpeg",".ts",".m2ts",".webm")
    if ($chkRecursive.Checked) {
        $movies = @(Get-ChildItem -LiteralPath $movieFolder -File -Recurse -ErrorAction SilentlyContinue |
            Where-Object { $exts -contains $_.Extension.ToLowerInvariant() })
    } else {
        $movies = @(Get-ChildItem -LiteralPath $movieFolder -File -ErrorAction SilentlyContinue |
            Where-Object { $exts -contains $_.Extension.ToLowerInvariant() })
    }

    if ($movies.Count -eq 0) {
        [System.Windows.Forms.MessageBox]::Show("No supported movie files were found.","No Movies")
        return
    }

    $script:CancelRequested = $false
    $script:CreatedCount = 0
    $script:StartTime = Get-Date
    $lblFound.Text = "$($movies.Count)"
    $lblCreated.Text = "0"
    $lblPercent.Text = "0%"
    $lblStatus.Text = "Starting..."
    $lblMovieNumber.Text = "Preparing movie list"
    $lblElapsed.Text = "Calculating..."
    $progressFill.Width = 0
    Add-Log "Found $($movies.Count) movie(s). Starting MP4 clip extraction." ([System.Drawing.Color]::LightSkyBlue)

    $index = 0
    foreach ($movie in $movies) {
        if ($script:CancelRequested) { break }
        $index++
        $lblCurrent.Text = [System.IO.Path]::GetFileNameWithoutExtension($movie.Name)
        $lblStatus.Text = "Processing"
        $lblMovieNumber.Text = "Movie $index of $($movies.Count)"
        $elapsed = (Get-Date) - $script:StartTime
        if ($index -gt 1) {
            $completedBeforeCurrent = $index - 1
            $avgSeconds = $elapsed.TotalSeconds / $completedBeforeCurrent
            $remainingMovies = $movies.Count - $completedBeforeCurrent
            $remainingSeconds = [Math]::Max(0, [Math]::Round($avgSeconds * $remainingMovies))
            $remaining = [TimeSpan]::FromSeconds($remainingSeconds)
            $lblElapsed.Text = $remaining.ToString("hh\:mm\:ss")
        } else {
            $lblElapsed.Text = "Calculating..."
        }
        [System.Windows.Forms.Application]::DoEvents()

        $durationText = & $ffprobe -v error -show_entries format=duration -of "default=noprint_wrappers=1:nokey=1" -- "$($movie.FullName)" 2>$null
        $duration = 0.0
        $ok = [double]::TryParse(
            ($durationText | Select-Object -First 1),
            [System.Globalization.NumberStyles]::Float,
            [System.Globalization.CultureInfo]::InvariantCulture,
            [ref]$duration
        )

        if (-not $ok -or $duration -le $clipLength) {
            Add-Log "Skipped: $($movie.Name) - could not obtain a usable duration." ([System.Drawing.Color]::Salmon)
        } else {
            $minStart = 0
            $maxStart = [Math]::Floor($duration - $clipLength)

            if ($avoid -gt 0 -and $duration -gt ($clipLength + ($avoid * 2))) {
                $minStart = $avoid
                $maxStart = [Math]::Floor($duration - $clipLength - $avoid)
            }

            if ($maxStart -le $minStart) {
                $start = $minStart
            } else {
                $start = Get-Random -Minimum $minStart -Maximum ($maxStart + 1)
            }

            $safeName = ([IO.Path]::GetFileNameWithoutExtension($movie.Name)) -replace '[\\/:*?"<>|]','_'

            # Recreate only the path BELOW the selected Movies Folder.
            # Normalize both paths first so a drive letter (for example V:\)
            # can never accidentally become part of the output path.
            $sourceRoot = [System.IO.Path]::GetFullPath($movieFolder).TrimEnd('\','/')
            $movieDirectory = [System.IO.Path]::GetFullPath($movie.DirectoryName).TrimEnd('\','/')
            $relativeDirectory = ""

            if ($movieDirectory.Equals($sourceRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
                $relativeDirectory = ""
            }
            elseif ($movieDirectory.StartsWith($sourceRoot + "\", [System.StringComparison]::OrdinalIgnoreCase)) {
                $relativeDirectory = $movieDirectory.Substring($sourceRoot.Length + 1)
            }

            # Safety: never allow a rooted/drive-qualified path to be appended
            # beneath the output folder.
            if ([System.IO.Path]::IsPathRooted($relativeDirectory) -or $relativeDirectory -match '^[A-Za-z]:') {
                $relativeDirectory = ""
            }

            $parentOut = $outputFolder
            if (-not [string]::IsNullOrWhiteSpace($relativeDirectory)) {
                $parentOut = Join-Path -Path $outputFolder -ChildPath $relativeDirectory
            }

            # Each video gets a movie folder and theme.mp4 is stored inside its backdrops directory.
            $movieOut = Join-Path $parentOut $safeName
            $backdropsOut = Join-Path $movieOut "backdrops"
            New-Item -ItemType Directory -Path $movieOut -Force | Out-Null
            New-Item -ItemType Directory -Path $backdropsOut -Force | Out-Null
            $outputFile = Join-Path $backdropsOut "theme.mp4"
            # Ask before replacing an existing clip for this movie.
            if (Test-Path -LiteralPath $outputFile) {
                $overwriteChoice = [System.Windows.Forms.MessageBox]::Show(
                    "A clip already exists for:`r`n`r`n$($movie.Name)`r`n`r`nDo you want to overwrite the existing theme.mp4?",
                    "Clip Already Exists",
                    [System.Windows.Forms.MessageBoxButtons]::YesNo,
                    [System.Windows.Forms.MessageBoxIcon]::Question
                )

                if ($overwriteChoice -ne [System.Windows.Forms.DialogResult]::Yes) {
                    Add-Log "Skipped existing clip: $outputFile"

                    # Count the skipped movie as processed so progress continues normally.
                    $pct = [Math]::Round(($index / $movies.Count) * 100)
                    $lblPercent.Text = "$($pct)%"
                    $progressFill.Width = [int]($progressTrack.Width * ($pct / 100.0))

                    $elapsed = (Get-Date) - $script:StartTime
                    if ($index -gt 0) {
                        $avgSeconds = $elapsed.TotalSeconds / $index
                        $remainingMovies = $movies.Count - $index
                        $remainingSeconds = [Math]::Max(0, [Math]::Round($avgSeconds * $remainingMovies))
                        $remaining = [TimeSpan]::FromSeconds($remainingSeconds)
                        $lblElapsed.Text = $remaining.ToString("hh\:mm\:ss")
                    }

                    [System.Windows.Forms.Application]::DoEvents()
                    continue
                }

                Add-Log "Overwrite confirmed: $outputFile"
            }


            $tc = [TimeSpan]::FromSeconds($start)
            Add-Log ("Creating theme.mp4 from {0} at {1:hh\:mm\:ss}" -f $movie.Name,$tc)
            $lblStatus.Text = "Creating MP4..."
            [System.Windows.Forms.Application]::DoEvents()

            & $ffmpeg -hide_banner -loglevel error -ss $start -i "$($movie.FullName)" -t $clipLength `
                -map 0:v:0 -map "0:a:0?" -c:v libx264 -preset fast -crf 20 `
                -c:a aac -b:a 192k -movflags +faststart -y "$outputFile"

            if ($LASTEXITCODE -eq 0 -and (Test-Path $outputFile)) {
                $script:CreatedCount++
                $lblCreated.Text = "$($script:CreatedCount)"
                $lblStatus.Text = "Clip created"
                Add-Log "Saved: $outputFile" ([System.Drawing.Color]::LightGreen)
            } else {
                Add-Log "FFmpeg failed: $($movie.Name)" ([System.Drawing.Color]::Salmon)
            }
        }

        $pct = [Math]::Round(($index / $movies.Count) * 100)
        $lblPercent.Text = "$($pct)%"
        $progressFill.Width = [int]($progressTrack.Width * ($pct / 100.0))
        $elapsed = (Get-Date) - $script:StartTime
        $avgSeconds = $elapsed.TotalSeconds / $index
        $remainingMovies = $movies.Count - $index
        $remainingSeconds = [Math]::Max(0, [Math]::Round($avgSeconds * $remainingMovies))
        $remaining = [TimeSpan]::FromSeconds($remainingSeconds)
        $lblElapsed.Text = $remaining.ToString("hh\:mm\:ss")
        [System.Windows.Forms.Application]::DoEvents()
    }

    if ($script:CancelRequested) {
        $lblStatus.Text = "Stopped"
        $lblMovieNumber.Text = "Processing cancelled"
        Add-Log "Processing stopped by user." ([System.Drawing.Color]::Orange)
    } else {
        $lblPercent.Text = "100%"
        $progressFill.Width = $progressTrack.Width
        $lblStatus.Text = "Complete"
        $lblElapsed.Text = "00:00:00"
        $lblMovieNumber.Text = "$($script:CreatedCount) clips created"
        Add-Log "Finished. Created $($script:CreatedCount) clip(s)." ([System.Drawing.Color]::LightGreen)
        $openResult = [System.Windows.Forms.MessageBox]::Show(
            "Finished.`r`n`r`nCreated $($script:CreatedCount) random clip(s).`r`n`r`nWould you like to open the output folder?",
            "Random Movie Clips",
            [System.Windows.Forms.MessageBoxButtons]::YesNo,
            [System.Windows.Forms.MessageBoxIcon]::Information
        )

        if ($openResult -eq [System.Windows.Forms.DialogResult]::Yes) {
            if (Test-Path $outputFolder) {
                Start-Process explorer.exe -ArgumentList "`"$outputFolder`""
            }
        }
    }
})

$form.Add_KeyDown({
    if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Escape) { $form.Close() }
})

Add-Log 'Ready. Select your folders and click "Create Random Clips".' ([System.Drawing.Color]::LightSkyBlue)
[void]$form.ShowDialog()

$background.Dispose()
$stream.Dispose()
